<script setup lang="ts">
import SchoolPhoto from '@/components/SchoolPhoto.vue';
import { schoolPhotos } from '@/assets/school-photos';
import { reactive, ref } from 'vue';
import PublicLayout from '@/layouts/PublicLayout.vue';
import ApplicationFields from '@/components/ApplicationFields.vue';
import ApiAlert from '@/components/ApiAlert.vue';
import { applicationPayload } from '@/utils/membership';
import { api, errorMessage } from '@/api/client';
import type { ApiResponse, ApplicationForm } from '@/types/api';
const form = reactive<ApplicationForm>({ fullName: '', email: '', phone: '', location: '', previousName: '', graduationYear: '', studentIndexNumber: '', lastClassAttended: '', verificationInformation: '' });
const receipt = ref<{ reference: string; secret: string; submittedAt: string } | null>(null);
const busy = ref(false), error = ref('');
async function submit() {
  busy.value = true; error.value = '';
  try { receipt.value = (await api.post<ApiResponse<NonNullable<typeof receipt.value>>>('/membership/applications', applicationPayload(form))).data.data; }
  catch (e) { error.value = errorMessage(e); } finally { busy.value = false; }
}
function download() {
  if (!receipt.value) return;
  const url = URL.createObjectURL(new Blob([`Gray D. Allison membership application\nReference: ${receipt.value.reference}\nPrivate tracking secret: ${receipt.value.secret}\nSubmitted: ${receipt.value.submittedAt}\nKeep this file private. Check status at ${window.location.origin}/membership/status`], { type: 'text/plain' }));
  const anchor = document.createElement('a'); anchor.href = url; anchor.download = 'gda-membership-tracking.txt'; anchor.click(); URL.revokeObjectURL(url);
}
</script>
<template><PublicLayout><section class="reference-ui form-reference mx-auto w-full max-w-[704px] px-4 pt-16 pb-12 md:pt-24"><header class="mb-10 text-center"><div class="mb-6 flex justify-center"><span aria-hidden="true" class="reference-crest material-symbols-outlined flex h-20 w-20 items-center justify-center rounded-sm bg-primary-container text-4xl text-white">school</span></div><h1 class="font-h1 mb-2 text-primary">Alumni Registration</h1><p class="font-body-md mx-auto max-w-md text-secondary">Join the official alumni network of Gray D. Allison High School. Your school records are reviewed before account activation.</p></header><ApiAlert :message="error"/><section v-if="receipt" class="space-y-5 border border-emerald-200 bg-white p-6" aria-live="polite"><h2 class="text-h2">Application submitted</h2><p>Save both credentials now. Your private tracking secret is shown only with this receipt. It is required to check status or correct a pending application.</p><label for="receipt" class="field-label">Private tracking credentials</label><textarea id="receipt" readonly class="field-input" rows="5" :value="`Reference: ${receipt.reference}\nTracking secret: ${receipt.secret}\nSubmitted: ${new Date(receipt.submittedAt).toLocaleString()}`"></textarea><button class="primary-button" @click="download">Download private receipt</button><RouterLink class="block underline" to="/membership/status">Check application status</RouterLink></section>
  <section v-else class="overflow-hidden border border-slate-200 bg-white shadow-sm"><ol aria-label="Membership registration process" class="flex border-b border-slate-200"><li aria-current="step" class="flex flex-1 items-center gap-3 border-r border-slate-200 bg-slate-50 px-6 py-4"><span aria-hidden="true" class="flex h-6 w-6 shrink-0 items-center justify-center rounded-full bg-primary text-xs font-bold text-white">1</span><span class="text-label-sm text-primary">Academic Details</span></li><li class="flex flex-1 items-center gap-3 px-6 py-4"><span aria-hidden="true" class="flex h-6 w-6 shrink-0 items-center justify-center rounded-full bg-secondary-container text-xs text-secondary">2</span><span class="text-label-sm text-secondary">Approval &amp; Activation</span></li></ol><form class="space-y-8 p-8" @submit.prevent="submit"><ApplicationFields :form="form" registration/><aside class="flex items-start gap-4 border-l-4 border-primary-container bg-slate-50 p-6"><span aria-hidden="true" class="material-symbols-outlined mt-0.5 text-primary-container">verified_user</span><div><h2 class="mb-1 text-label-sm text-primary">School Records Verification</h2><p class="text-caption text-secondary">The registrar verifies your attendance before approving membership. You will create your password using your private activation invitation after approval.</p></div></aside><div class="flex items-start gap-2 py-4"><input id="membership-policies" type="checkbox" required class="mt-0.5 h-4 w-4 shrink-0 accent-primary"><label for="membership-policies" class="text-caption text-on-surface-variant">I have read the <RouterLink to="/terms" class="underline">Terms of Service</RouterLink> and <RouterLink to="/privacy" class="underline">Privacy Policy</RouterLink>.</label></div><div class="flex flex-wrap items-center justify-between gap-4 pt-4"><RouterLink to="/login" class="text-label-sm text-primary hover:underline">Already registered? Login</RouterLink><button class="primary-button" :disabled="busy">{{ busy ? 'Submitting…' : 'Submit application' }}<span aria-hidden="true" class="material-symbols-outlined text-sm">chevron_right</span></button></div><RouterLink to="/membership/status" class="block text-center text-sm underline">Already applied? Check application status</RouterLink></form></section><div class="mt-12 grid grid-cols-3 gap-4"><div v-for="photo in [schoolPhotos.graduates, schoolPhotos.schoolGroup, schoolPhotos.band]" :key="photo.id" class="h-32 bg-slate-100"><SchoolPhoto :photo="photo" /></div></div></section></PublicLayout></template>
